-- Independent Tabor Academy Survival & Mastery Domains.

WITH new_paths(slug, local_order, title, purpose, coverage, namespace_name) AS (VALUES
  ('survival-mastery-domains', 1, 'Six Universal Human Survival & Mastery Domains', 'Start at 0 or choose one of six domains. Link the Nine Pillars, Human Learning Arc, and practical decision-making without changing their courses.', 'Protection; money and contracts; kinship; homestead; meta-learning; institutional literacy.', 'tabor-academy-way-survival-mastery-domains-dev'),
  ('mastery-protection', 2, 'Protection', 'Observe conduct, create distance, get help and rehearse an emergency handoff.', 'Threat cues · de-escalation · first aid', 'tabor-academy-way-mastery-protection-dev'),
  ('mastery-money', 3, 'Money, Trade & Contracts', 'Read the written terms and put costs, dates, and obligations on a checkable record.', 'Exchange · agreements · cash flow', 'tabor-academy-way-mastery-money-dev'),
  ('mastery-kinship', 4, 'Human Psychology & Relationships', 'Separate observations from assumptions, establish boundaries, and rehearse accountability.', 'Consent · trust · repair', 'tabor-academy-way-mastery-kinship-dev'),
  ('mastery-homestead', 5, 'Domestic & Homestead Core', 'Plan reliable daily services and use models to find maintenance and safety decisions.', 'Water · food · shelter', 'tabor-academy-way-mastery-homestead-dev'),
  ('mastery-learning', 6, 'Meta-Learning & Mind Architecture', 'Compare practice formats, retrieve what you learned, and revise rules when a real test calls for it.', 'Access · recall · revision', 'tabor-academy-way-mastery-learning-dev'),
  ('mastery-civic', 7, 'Civic Reality & Institutional Literacy', 'Find the correct authority, read the record, and rehearse a question or next step.', 'Records · procedure · public decisions', 'tabor-academy-way-mastery-civic-dev')
)
SELECT slug, (SELECT COALESCE(MAX(position), 0) FROM academy_way_paths) + local_order,
  title, purpose, coverage, namespace_name
FROM new_paths
WHERE true
ON CONFLICT(slug) DO NOTHING;

ON CONFLICT(slug) DO NOTHING;
