INSERT INTO academy_way_paths (slug, position, title, purpose, coverage, namespace_name)
INSERT INTO academy_way_missions (slug, path, position, title, outcome, build, flip, integrate, verify, link) VALUES
  ('survival-mastery-zero', 'survival-mastery-domains', 500, '0 · Start from a real decision', 'Choose a fictional scenario and produce an action that another learner can check. Use any domain as an entry point.', '1+1=2. Write down a goal, the people affected, the facts you can verify and the resources available.', '1−1=0. Clear unsupported assumptions. Mark danger, urgency, missing information and when to reach qualified help.', '1×1=1. Rehearse a response with a model, document, role card or sample data. Use a second domain when the decision crosses one.', '1÷1=1. Ask another learner to replay your decision from the record. For a complete run, do the six-domain capstone.', 'way/mastery-civic/survival-domain-27/'),
  ('survival-mastery-protection', 'survival-mastery-domains', 501, 'Protection', 'Observe conduct, create distance, get help and rehearse an emergency handoff.', 'Select a case and name the decision you have to make.', 'Identify assumptions and the evidence that would change the decision.', 'Rehearse one action in the domain and explain who else may need to act.', 'Use the worked check and write what you can now demonstrate.', 'way/mastery-protection/'),
  ('survival-mastery-money', 'survival-mastery-domains', 502, 'Money, Trade & Contracts', 'Read the written terms and put costs, dates, and obligations on a checkable record.', 'Select a case and name the decision you have to make.', 'Identify assumptions and the evidence that would change the decision.', 'Rehearse one action in the domain and explain who else may need to act.', 'Use the worked check and write what you can now demonstrate.', 'way/mastery-money/'),
  ('survival-mastery-kinship', 'survival-mastery-domains', 503, 'Human Psychology & Relationships', 'Separate observations from assumptions, establish boundaries, and rehearse accountability.', 'Select a case and name the decision you have to make.', 'Identify assumptions and the evidence that would change the decision.', 'Rehearse one action in the domain and explain who else may need to act.', 'Use the worked check and write what you can now demonstrate.', 'way/mastery-kinship/'),
  ('survival-mastery-homestead', 'survival-mastery-domains', 504, 'Domestic & Homestead Core', 'Plan reliable daily services and use models to find maintenance and safety decisions.', 'Select a case and name the decision you have to make.', 'Identify assumptions and the evidence that would change the decision.', 'Rehearse one action in the domain and explain who else may need to act.', 'Use the worked check and write what you can now demonstrate.', 'way/mastery-homestead/'),
  ('survival-mastery-learning', 'survival-mastery-domains', 505, 'Meta-Learning & Mind Architecture', 'Compare practice formats, retrieve what you learned, and revise rules when a real test calls for it.', 'Select a case and name the decision you have to make.', 'Identify assumptions and the evidence that would change the decision.', 'Rehearse one action in the domain and explain who else may need to act.', 'Use the worked check and write what you can now demonstrate.', 'way/mastery-learning/'),
  ('survival-mastery-civic', 'survival-mastery-domains', 506, 'Civic Reality & Institutional Literacy', 'Find the correct authority, read the record, and rehearse a question or next step.', 'Select a case and name the decision you have to make.', 'Identify assumptions and the evidence that would change the decision.', 'Rehearse one action in the domain and explain who else may need to act.', 'Use the worked check and write what you can now demonstrate.', 'way/mastery-civic/'),
  ('survival-mastery-nine-pillars', 'survival-mastery-domains', 507, 'The Nine Operational Pillars', 'Locate where a practical skill sits in the Academy curriculum and how it is assessed.', 'Find the Academy institution page and choose one pillar related to your skill.', 'Separate the learning objective from the evidence of mastery.', 'Trace a skill through scope, lesson, rubric, and records.', 'Name the pillar responsible for the outcome and show the link to the exercise.', 'institution/'),
  ('survival-mastery-learning-arc', 'survival-mastery-domains', 508, 'The Complete Human Learning Arc', 'Trace a practical skill over time and compare the evidence across two eras.', 'Choose one World or Academy example from the Human Learning Arc.', 'Separate historical observation from a modern scenario or proposed future.', 'Carry one question from the arc into the corresponding survival and mastery domain.', 'Cite the age, setting, or scenario behind each example you compared.', 'way/human-learning-arc/'),
  ('survival-domain-01', 'mastery-protection', 509, 'Situational Threat & Predatory Pattern Recognition', 'Make a record of observed conduct that a partner can check.', 'Ask: What can you observe before deciding whether to leave or report?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Sort fictional cards showing a blocked exit, repeated requests for secrecy, a changed account, and a neutral disagreement. Write what happened, who could help, and how you can leave safely. Use NCMEC''s prevention material for the grooming example.', 'Classify conduct and context rather than appearance or identity. A blocked exit or credible immediate threat calls for distance and emergency help. Document words or actions rather than assigning motives.', 'way/language/gaslighting-and-plain-truth/'),
  ('survival-domain-02', 'mastery-protection', 510, 'De-escalation, Verbal Judo & Command Presence', 'Make three short de-escalation scripts that a partner can check.', 'Ask: When is a calm verbal response appropriate, and when is leaving safer?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Role-play a line dispute using one acknowledgment, one clear request, and an option to disengage. Have an observer track volume, distance and exit access. Change the scenario to include a credible threat and practice calling for help instead.', 'The calm version uses space, a neutral tone, and a clear exit. If violence appears imminent, leave if safe and contact emergency services. Check against CISA''s De-escalation Action Guide.', 'way/mastery-protection/survival-domain-03/'),
  ('survival-domain-03', 'mastery-protection', 511, 'Emergency Triage, Trauma & Field Medicine', 'Make four first-aid decision cards that a partner can check.', 'Ask: Which action happens first when the scene and injury both demand attention?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Use a tabletop scene with severe bleeding, a suspected fracture, a thermal burn, and possible shock. Assign who checks scene safety, calls 911 or the local emergency number, brings a kit and relays observations. Practice direct pressure on a training pad. Use the AHA and American Red Cross first-aid guidelines for the care cards.', 'Call early and follow dispatcher instructions. Practice pressure on the training pad. In the fracture card support the limb in the position found and leave alignment to trained responders. Compare the burn and shock handoffs with the source guideline.', 'way/mastery-protection/survival-domain-18/'),
  ('survival-domain-18', 'mastery-protection', 512, 'Household Emergency Planning & Accessible Evacuation', 'Make two exits and a backup contact that a partner can check.', 'Ask: Can everyone reach the agreed meeting place if one exit closes?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Run a fictional outage and evacuation with an inaccessible exit and a silent phone. Draw alternate routes, alerts, check-in and a place to meet. Include mobility, language, medication, and service-animal needs in the paper trial.', 'Each person has an accessible fallback and another way to get help. A second household can explain the plan from the written card.', 'way/mastery-protection/survival-domain-19/'),
  ('survival-domain-19', 'mastery-protection', 513, 'Safe Bystander Support & Reporting', 'Make an observed-incident handoff that a partner can check.', 'Ask: What help can you offer without escalating the danger?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Role-play a fictional event in a shared space. Choose between creating distance, getting staff, contacting emergency services and checking on the person when safe. Draft a report containing time, location and observations.', 'The report distinguishes what was seen from what was told. The response protects privacy and gives the affected person choices where possible.', 'way/survival-mastery-domains/'),
  ('survival-domain-04', 'mastery-money', 514, 'Barter, Direct Exchange & Value Creation', 'Make a written agreement for an exchange that a partner can check.', 'Ask: Can either person explain what counts as finished?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Trade fictitious repair work for garden produce. Write the quantity, delivery dates, condition, agreed value, and what happens if either delivery fails. Ask a partner to read the agreement back.', 'Both sides can identify what is owed. Keep records and check reporting rules for barter in the relevant jurisdiction.', 'way/mastery-money/survival-domain-05/'),
  ('survival-domain-05', 'mastery-money', 515, 'Contract Forensics & Loophole Spotting', 'Make two sample contract clauses that a partner can check.', 'Ask: What does the document actually promise?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Mark the parties, fee, renewal, cancellation deadline, notice method, and remedy in a fictional lease or service plan. Compare a headline promise with the clause that would govern it.', 'A useful review quotes the actual clause, names the unanswered question, and records whether the governing law, enforceability or legal help needs to be checked.', 'way/mastery-money/survival-domain-06/'),
  ('survival-domain-06', 'mastery-money', 516, 'Tax, Debt & Currency Mechanics', 'Make a loan and purchasing-power comparison that a partner can check.', 'Ask: What changes when a lower payment lasts longer?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Compare fictional loan A at 90 per month for 12 months and loan B at 60 per month for 20 months, each on a principal of 1,000 before any separate fees. Calculate total payments. Compare the amount of a fixed basket that can be purchased before and after a price increase.', 'A totals 1,080 and B totals 1,200 on the supplied numbers. Separate principal, total cost, APR and fees. Keep inflation as purchasing-power change and check tax rules through official sources for the relevant jurisdiction.', 'way/mastery-money/survival-domain-20/'),
  ('survival-domain-20', 'mastery-money', 517, 'Cash Flow, Reserves & Fraud Checks', 'Make a four-week cash calendar that a partner can check.', 'Ask: Which bill comes due before the money arrives?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Use the CFPB''s cash-flow worksheet on a fictional case: starting cash 100, a bill of 150 on Monday and pay of 400 on Friday. Mark the shortfall and propose two ways to change timing or reserve cash. Add a fictional demand for urgent wire payment and verify it through an independently located channel.', 'The Monday shortfall is 50, even though the week ends ahead. A verification plan checks the source independently and records a way to report suspected fraud.', 'way/survival-mastery-domains/'),
  ('survival-domain-07', 'mastery-kinship', 518, 'Attachment, Trauma & Generational Cycles', 'Make a fictional pattern and alternative response that a partner can check.', 'Ask: What can change without guessing the other person''s diagnosis?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Chart trigger, observable reaction, effect, and one possible response in a fictional family disagreement. Use SAMHSA''s safety, trust, collaboration and choice principles to design an alternate exchange. Personal disclosure is optional.', 'The improved script offers a choice, acknowledges impact and identifies support. Separate observed behavior, inferred motives, and a clinical conclusion.', 'way/mastery-kinship/survival-domain-08/'),
  ('survival-domain-08', 'mastery-kinship', 519, 'Boundary Enforcement & "Yes Means Yes / No Means No"', 'Make three requests and a boundary script that a partner can check.', 'Ask: Can a person say no or change their mind without pressure?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Practice declining a request to share a private file. A second person accepts the answer and repeats it accurately. Run a new scenario where a previous yes changes to no.', 'Silence and pressure leave consent unestablished. A change of mind ends the permission for that action. Document only what is appropriate to share.', 'way/mastery-kinship/survival-domain-09/'),
  ('survival-domain-09', 'mastery-kinship', 520, 'Choosing Partners, Allies & Friends', 'Make a reliability timeline that a partner can check.', 'Ask: Which pattern is established by actions over time?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Read three fictional commitments and six later actions. Compare follow-through, respect for boundaries, and response to a mistake. Assign each claim a dated observation or mark it open.', 'A strong explanation allows new evidence and recognizes repair. Repeated behavior and one isolated incident carry different information.', 'way/mastery-kinship/survival-domain-21/'),
  ('survival-domain-21', 'mastery-kinship', 521, 'Repair After Conflict & Support Networks', 'Make a repair script and support map that a partner can check.', 'Ask: What would accountability look like after a trust breach?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Use a fictional broken promise. Write an apology naming the action and impact, one practical repair, and a follow-up check. List alternative support for a person who chooses distance.', 'The repair is observable and optional for the recipient. A support map names multiple ways to get help without requiring renewed contact.', 'way/survival-mastery-domains/'),
  ('survival-domain-10', 'mastery-homestead', 522, 'Water Sourcing, Filtration & Storage', 'Make household water advisory cards that a partner can check.', 'Ask: Which advisory changes the source you can use?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Match service interruption, a boil-water notice, and suspected fuel contamination to the response in supplied CDC guidance. Sketch a dated backup storage and resupply plan without experimenting on suspect water.', 'The response follows the local advisory. Boiling addresses germs and does not remove fuel or toxic chemicals. Use a verified alternate source when the guidance calls for one.', 'way/mastery-homestead/survival-domain-11/'),
  ('survival-domain-11', 'mastery-homestead', 523, 'Food Preservation & Long-Term Storage', 'Make a preservation-method decision sheet that a partner can check.', 'Ask: Which tested procedure matches the food and conditions?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Open the National Center for Home Food Preservation guidance. Match a low-acid vegetable, a permitted dried product, and a cold-storage scenario to an applicable tested method. Record method, conditions and label details with no tasting of suspect food.', 'Low-acid home canning requires the applicable tested pressure-canning process. Smoking, salting and drying have separate requirements. Check the exact recipe, equipment and elevation before any real processing.', 'way/mastery-homestead/survival-domain-12/'),
  ('survival-domain-12', 'mastery-homestead', 524, 'Plumbing, Framing, Roofing & Basic Repair', 'Make a model home inspection sheet that a partner can check.', 'Ask: Which symptom can you record from a safe position?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Mark the likely water path, shutoff and visible damage on a model or ground-level photo. Demonstrate a fabric patch or a removable mock plumbing connection. Compare a framing diagram, a roof diagram and a de-energized circuit illustration.', 'A strong handoff names what can be observed, a way to limit damage without exposure, and when a plumber, electrician, roofer or other qualified worker is needed.', 'way/human-arc-mechanical/human-arc-method-19/'),
  ('survival-domain-22', 'mastery-homestead', 525, 'Fire, Carbon Monoxide & Utility Shutoff Planning', 'Make a model alarm-and-exit map that a partner can check.', 'Ask: Where do people go when the alarm sounds?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Mark smoke and carbon monoxide alarms, two routes, a meeting spot and responder access on a model home plan. Use U.S. Fire Administration guidance to review safe alarm responses. Put the utility contact on the plan.', 'People can explain where to go and whom to call from safety. The exercise locates shutoffs on a diagram and leaves hazardous interventions to the utility or responder.', 'way/mastery-homestead/survival-domain-23/'),
  ('survival-domain-23', 'mastery-homestead', 526, 'Outage Sanitation & Inventory Rotation', 'Make an outage supply and hygiene board that a partner can check.', 'Ask: Which routine fails if water or power stays off?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Plan a tabletop outage with drinking water, hygiene, sanitation, temperature-sensitive supplies and waste collection tracked separately. Add a date and replenishment flag to each supply. Review current local advisories before the simulated restart.', 'The plan keeps drinking water and other uses visible, names a resupply threshold, and identifies what depends on health or utility instructions.', 'way/human-arc-future/human-arc-method-30/'),
  ('survival-domain-13', 'mastery-learning', 527, 'Neuro-Diversity & Processing Styles', 'Make three versions of one instruction that a partner can check.', 'Ask: Which representation helps with this task for this learner?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Offer a forward list, a reverse dependency sketch and a hands-on demonstration of the same simple task. Make each available in accessible formats and check performance on a new example.', 'Use the recorded result to select an accommodation or representation for that task. A preference or a single trial gives no fixed learning-style classification.', 'way/mastery-learning/survival-domain-14/'),
  ('survival-domain-14', 'mastery-learning', 528, 'Memory Compression & Recall Systems', 'Make a rhythm, diagram or story with an answer key that a partner can check.', 'Ask: Which details survive when the cue is gone?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Group eight fictional steps into three chunks. Make a rhythm, story, or map, then cover it and recall the steps. Compare after a delay and retest with a changed example using the IES study guide.', 'Score accuracy and transfer separately. Record details that compression dropped and retrieve them again after spacing the practice.', 'way/mastery-learning/survival-domain-15/'),
  ('survival-domain-15', 'mastery-learning', 529, 'Unlearning & Resetting ("1 - 1 = 0")', 'Make an old rule beside its revision that a partner can check.', 'Ask: Which counterexample makes an old rule fail?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Begin with a fictional reasoning shortcut. Find a case it gets wrong, state the replacement rule and write a test that would expose a problem with the replacement.', 'Keep the old rule dated next to the revision, the reason for the change, and one result that would merit revisiting the new rule.', 'way/mastery-learning/survival-domain-24/'),
  ('survival-domain-24', 'mastery-learning', 530, 'Accessible Practice & Progress Tracking', 'Make two accessible versions and a transfer test that a partner can check.', 'Ask: Can a learner reach the same goal with different supports?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Set one measurable goal for a simple skill. Offer a text-first and a model-first exercise, both with keyboard or paper alternatives. Run a delayed recall and a different practical case.', 'Compare task completion, learner effort and transfer. Keep the shared objective and adapt the format using the learner''s feedback.', 'way/survival-mastery-domains/'),
  ('survival-domain-16', 'mastery-civic', 531, 'Public Records, FOIA & Legal Self-Representation', 'Make a mock records request and docket that a partner can check.', 'Ask: Which office holds which record?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Sort a fictional federal environmental record, a North Carolina county agenda, and a court docket. Draft a narrow dated request for one existing record and make a separate court calendar using the example court''s official forms and rules.', 'Use FOIA.gov for the federal agency example, local or state rules for the county, and the court''s own records process for the docket. Confirm the actual jurisdiction and deadline before relying on an example.', 'way/mastery-civic/survival-domain-17/'),
  ('survival-domain-17', 'mastery-civic', 532, 'Local Governance & Zoning Mechanics', 'Make a fictional parcel and decision chain that a partner can check.', 'Ask: Which office can confirm the rule that applies?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Read a sample parcel map and ordinance excerpt. Mark jurisdiction, district, proposed use, possible exemptions and the relevant decision-maker. Use North Carolina Chapter 160D as one jurisdictional example and prepare a question for the planner.', 'Record the current dated local rule and office. Check the conditions and scope of any agricultural exemption before assuming it applies.', 'way/mastery-civic/survival-domain-25/'),
  ('survival-domain-25', 'mastery-civic', 533, 'Agendas, Budgets, Public Comment & Appeals', 'Make a mock board record that a partner can check.', 'Ask: Who decided, under what procedure, and when can the decision be reviewed?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Read a fictional agenda, minutes, vote and budget line. Write a one-minute comment that quotes the item and asks for a specific response. Make a record of where to find the applicable review or appeal process.', 'The record distinguishes a discussion, recommendation, and adoption. Use the actual body''s notice and official procedure to confirm deadlines.', 'way/mastery-civic/survival-domain-26/'),
  ('survival-domain-26', 'mastery-civic', 534, 'Benefits, Public Services & Administrative Review', 'Make a fictional agency notice that a partner can check.', 'Ask: Which facts and dates determine what to ask next?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'On a fictional service-denial notice, circle the agency, dates, stated reason and contact paths. Draft a factual request for clarification and make a checklist for asking about accommodations or review.', 'The handoff quotes the exact reason and confirms process at the issuing agency. It keeps full private identifiers off public forms or class materials.', 'way/mastery-civic/survival-domain-27/'),
  ('survival-domain-27', 'mastery-civic', 535, 'Six-Domain Capstone · One Household Scenario', 'Make one decision log across all six domains that a partner can check.', 'Ask: Can another person replay the whole response from the evidence?', 'State your first choice. Record which observation, term, current source, or worked calculation could change it.', 'Run a fictional storm outage with a questionable repair offer, a disagreement, a water notice, a new procedure to remember, and a county announcement. Each role produces a checkable move from one domain, then compare who helps whom.', 'The decision log shows a safety action, a money check, a boundary, a homestead step, a recall test, and a civic source. Record the first action you would revise and why.', 'way/survival-mastery-domains/')
